def dll_delete_kth(head, k):
    node = head
    position = 1
    while node is not None and position < k:
        node = node.next
        position += 1
    if node is None:
        return head
    if node.prev is not None:
        node.prev.next = node.next
    else:
        head = node.next
    if node.next is not None:
        node.next.prev = node.prev
    node.prev = node.next = None
    return head

