def intersection_node(headA, headB):
    a, b = headA, headB
    while a is not b:
        a = a.next if a is not None else headB
        b = b.next if b is not None else headA
    return a

def has_cycle(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

def cycle_start(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            finder = head
            while finder is not slow:
                finder = finder.next
                slow = slow.next
            return finder
    return None

def loop_length(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            length = 1
            walker = slow.next
            while walker is not slow:
                walker = walker.next
                length += 1
            return length
    return 0

def flatten(head):
    def merge(a, b):
        dummy = ChildNode(0)
        tail = dummy
        while a is not None and b is not None:
            if a.val <= b.val:
                tail.child, a = a, a.child
            else:
                tail.child, b = b, b.child
            tail = tail.child
            tail.next = None
        tail.child = a if a is not None else b
        return dummy.child

    if head is None or head.next is None:
        return head
    rest = flatten(head.next)
    head.next = None
    return merge(head, rest)

def dll_delete_all(head, key):
    node = head
    while node is not None:
        following = node.next
        if node.val == key:
            if node.prev is not None:
                node.prev.next = node.next
            else:
                head = node.next
            if node.next is not None:
                node.next.prev = node.prev
        node = following
    return head

def dll_remove_duplicates(head):
    node = head
    while node is not None and node.next is not None:
        if node.next.val == node.val:
            duplicate = node.next
            node.next = duplicate.next
            if duplicate.next is not None:
                duplicate.next.prev = node
        else:
            node = node.next
    return head
